import React, { useState } from 'react';

const Home = () => {
  // Liste fictive de cours pour l'affichage sur la page d'accueil
  const [courses, setCourses] = useState([
    { id: 1, title: "Hacking Éthique & Pentest : Les Fondations", level: "Débutant", price: 25000, previewVideo: "https://www.youtube.com/embed/dQw4w9WgXcQ" },
    { id: 2, title: "Sécurisation des Architectures Réseaux & pfSense", level: "Avancé", price: 40000, previewVideo: "https://www.youtube.com/embed/dQw4w9WgXcQ" }
  ]);

  const [selectedCourse, setSelectedCourse] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState('');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);

  const handleOpenPaymentModal = (course) => {
    setSelectedCourse(course);
    setPaymentMethod('');
    setPaymentSuccess(false);
  };

  const handleSimulatePayment = (e) => {
    e.preventDefault();
    if (!paymentMethod) return;

    setIsProcessingPayment(true);

    // Simulation de la latence réseau (3 secondes) conformément au brief
    setTimeout(() => {
      setIsProcessingPayment(false);
      setPaymentSuccess(true);
    }, 3000);
  };

  return (
    <div className="min-h-screen bg-[#030712] text-gray-100 font-sans">
      {/* Barre de navigation / En-tête */}
      <header className="border-b border-slate-800 bg-gray-900 px-6 py-4 flex justify-between items-center">
        <h1 className="text-xl font-bold text-emerald-400 tracking-wide">Avalon Secure Academy</h1>
        <div className="flex gap-4">
          <a href="/login" className="text-gray-400 hover:text-white text-sm font-medium self-center">Se connecter</a>
          <a href="/register" className="bg-emerald-500 text-gray-950 px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-400 transition">
            S'inscrire
          </a>
        </div>
      </header>

      {/* Section Héro / Vision */}
      <main className="max-w-6xl mx-auto px-4 py-12">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-extrabold mb-4">Maîtrisez la Cybersécurité et les Réseaux</h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            Des formations pratiques conçues pour le marché africain. Apprenez à votre rythme avec un accès à vie.
          </p>
        </div>

        {/* Grille des Cours disponibles */}
        <div className="grid md:grid-cols-2 gap-8">
          {courses.map((course) => (
            <div key={course.id} className="bg-gray-900 border border-slate-800 rounded-xl p-6 flex flex-col justify-between shadow-lg">
              <div>
                <span className="inline-block bg-slate-800 text-emerald-400 text-xs px-2.5 py-1 rounded-full font-semibold mb-4">
                  {course.level}
                </span>
                <h3 className="text-xl font-bold mb-2">{course.title}</h3>
                <p className="text-2xl font-black text-emerald-400 mb-6">{course.price.toLocaleString()} FCFA</p>
              </div>
              
              <button
                onClick={() => handleOpenPaymentModal(course)}
                className="w-full bg-slate-950 hover:bg-slate-800 text-gray-200 border border-slate-800 font-bold py-3 rounded-lg transition"
              >
                Acheter ce cours (Accès à vie)
              </button>
            </div>
          ))}
        </div>
      </main>

      {/* MODAL DE PAIEMENT SIMULÉ (SANDBOX 4 MOYENS DE PAIEMENT) */}
      {selectedCourse && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="w-full max-w-md bg-gray-900 border border-slate-800 rounded-xl p-6 relative shadow-2xl">
            
            {/* Bouton Fermer */}
            <button 
              onClick={() => setSelectedCourse(null)} 
              className="absolute top-4 right-4 text-gray-500 hover:text-white text-xl"
            >
              ✕
            </button>

            {!paymentSuccess ? (
              <>
                <h3 className="text-lg font-bold mb-1">Finaliser votre achat</h3>
                <p className="text-sm text-gray-400 mb-4">{selectedCourse.title}</p>
                
                <div className="bg-[#030712] p-3 rounded-lg border border-slate-800 flex justify-between items-center mb-6">
                  <span className="text-sm text-gray-400">Montant unique :</span>
                  <span className="text-xl font-bold text-emerald-400">{selectedCourse.price.toLocaleString()} FCFA</span>
                </div>

                <form onSubmit={handleSimulatePayment} className="space-y-6">
                  {/* Les 4 moyens de paiement demandés */}
                  <div>
                    <label className="block text-sm text-gray-400 mb-3">Choisissez votre moyen de paiement :</label>
                    <div className="grid grid-cols-2 gap-3">
                      
                      {/* MTN Mobile Money */}
                      <button
                        type="button"
                        onClick={() => setPaymentMethod('mtn')}
                        className={`p-3 rounded-lg border flex flex-col items-center justify-center gap-1 transition ${paymentMethod === 'mtn' ? 'border-yellow-500 bg-yellow-500/10 text-yellow-500' : 'border-slate-800 bg-[#030712] hover:bg-slate-800'}`}
                      >
                        <span className="font-bold text-sm">MTN MoMo</span>
                      </button>

                      {/* Wave */}
                      <button
                        type="button"
                        onClick={() => setPaymentMethod('wave')}
                        className={`p-3 rounded-lg border flex flex-col items-center justify-center gap-1 transition ${paymentMethod === 'wave' ? 'border-blue-400 bg-blue-400/10 text-blue-400' : 'border-slate-800 bg-[#030712] hover:bg-slate-800'}`}
                      >
                        <span className="font-bold text-sm">Wave</span>
                      </button>

                      {/* Carte Bancaire */}
                      <button
                        type="button"
                        onClick={() => setPaymentMethod('card')}
                        className={`p-3 rounded-lg border flex flex-col items-center justify-center gap-1 transition ${paymentMethod === 'card' ? 'border-emerald-400 bg-emerald-400/10 text-emerald-400' : 'border-slate-800 bg-[#030712] hover:bg-slate-800'}`}
                      >
                        <span className="font-bold text-sm">Carte Bancaire</span>
                      </button>

                      {/* PayPal */}
                      <button
                        type="button"
                        onClick={() => setPaymentMethod('paypal')}
                        className={`p-3 rounded-lg border flex flex-col items-center justify-center gap-1 transition ${paymentMethod === 'paypal' ? 'border-indigo-400 bg-indigo-400/10 text-indigo-400' : 'border-slate-800 bg-[#030712] hover:bg-slate-800'}`}
                      >
                        <span className="font-bold text-sm">PayPal</span>
                      </button>

                    </div>
                  </div>

                  {/* Bouton d'action principal ou Écran de chargement */}
                  {isProcessingPayment ? (
                    <div className="w-full flex flex-col items-center justify-center py-3 bg-slate-950 border border-slate-800 rounded-lg gap-2">
                      <div className="w-5 h-5 border-2 border-emerald-400 border-t-transparent rounded-full animate-spin"></div>
                      <span className="text-xs text-gray-400">Connexion sécurisée au réseau marchand...</span>
                    </div>
                  ) : (
                    <button
                      type="submit"
                      disabled={!paymentMethod}
                      className={`w-full py-3 rounded-lg font-bold transition ${paymentMethod ? 'bg-emerald-500 text-gray-950 hover:bg-emerald-400' : 'bg-gray-800 text-gray-500 cursor-not-allowed'}`}
                    >
                      Simuler le paiement
                    </button>
                  )}
                </form>
              </>
            ) : (
              /* ÉCRAN DE SUCCÈS APRÈS LES 3 SECONDES DE LOADER */
              <div className="text-center py-6">
                <div className="text-emerald-400 text-5xl mb-4">🎉</div>
                <h3 className="text-2xl font-bold mb-2">Paiement validé !</h3>
                <p className="text-gray-400 text-sm mb-6">
                  Le cours a été débloqué avec succès. Vous disposez maintenant d'un accès complet et à vie.
                </p>
                <button
                  onClick={() => setSelectedCourse(null)}
                  className="w-full bg-emerald-500 text-gray-950 font-bold py-3 rounded-lg hover:bg-emerald-400 transition"
                >
                  Ouvrir ma formation
                </button>
              </div>
            )}

          </div>
        </div>
      )}
    </div>
  );
};

export default Home;
